var dynamicAllowlist = new Set(EMBEDDED_OFFICIAL_DOMAINS);
function updateAllowlist(newDomains) {
  for (const d of newDomains) {
    dynamicAllowlist.add(d.toLowerCase());
  }
}
function isOfficialSync(host) {
  const clean = host.toLowerCase().trim();
  if (dynamicAllowlist.has(clean))
    return true;
  const parts = clean.split(".");
  for (let i = 1; i < parts.length - 1; i++) {
    const parent = parts.slice(i).join(".");
    if (dynamicAllowlist.has(parent))
      return true;
  }
  return false;
}

// src/dnr.ts
var MAX_DNR_RULES = 5e3;
var RULE_BASE_ID = 1e4;
var hostToRuleId = /* @__PURE__ */ new Map();
var nextRuleId = RULE_BASE_ID;
function nextId() {
  const id = nextRuleId++;
  if (nextRuleId > RULE_BASE_ID + MAX_DNR_RULES)
    nextRuleId = RULE_BASE_ID;
  return id;
}
async function blockHost(host) {
  const clean = host.toLowerCase().trim();
  if (hostToRuleId.has(clean))
    return;
  const ruleId = nextId();
  hostToRuleId.set(clean, ruleId);
  const rule = {
    id: ruleId,
    priority: 100,
    action: { type: "block" },
    condition: {
      urlFilter: `||${clean}^`,
      resourceTypes: ["main_frame"]
    }
  };
  try {
    await chrome.declarativeNetRequest.updateDynamicRules({
      addRules: [rule],
      removeRuleIds: []
    });
  } catch (err) {
    console.warn("[SiteGuard] DNR blockHost failed:", err);
    hostToRuleId.delete(clean);
  }
}

